using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;

public static class ControlTheme {
    public static void Primary(Button button){button.Background=Dock.B("#ADDCD5");button.Foreground=Dock.B("#203638");button.FontWeight=FontWeights.SemiBold;FluidMotion.Press(button);}
    public static void Install(Application app){
        app.Resources[typeof(System.Windows.Controls.Primitives.ScrollBar)]=(Style)System.Windows.Markup.XamlReader.Parse("<Style xmlns='http://schemas.microsoft.com/winfx/2006/xaml/presentation' xmlns:x='http://schemas.microsoft.com/winfx/2006/xaml' TargetType='{x:Type ScrollBar}'><Setter Property='Width' Value='5'/><Setter Property='Background' Value='Transparent'/><Setter Property='Template'><Setter.Value><ControlTemplate TargetType='{x:Type ScrollBar}'><Track x:Name='PART_Track' Orientation='Vertical' IsDirectionReversed='True' Minimum='{TemplateBinding Minimum}' Maximum='{TemplateBinding Maximum}' Value='{TemplateBinding Value}' ViewportSize='{TemplateBinding ViewportSize}'><Track.DecreaseRepeatButton><RepeatButton Command='{x:Static ScrollBar.PageUpCommand}'><RepeatButton.Template><ControlTemplate><Border Background='Transparent'/></ControlTemplate></RepeatButton.Template></RepeatButton></Track.DecreaseRepeatButton><Track.Thumb><Thumb MinHeight='24'><Thumb.Template><ControlTemplate TargetType='{x:Type Thumb}'><Border x:Name='Grip' Background='#526E8299' CornerRadius='2' Width='4' HorizontalAlignment='Center'/><ControlTemplate.Triggers><Trigger Property='IsMouseOver' Value='True'><Setter TargetName='Grip' Property='Background' Value='#91ADC3DD'/></Trigger></ControlTemplate.Triggers></ControlTemplate></Thumb.Template></Thumb></Track.Thumb><Track.IncreaseRepeatButton><RepeatButton Command='{x:Static ScrollBar.PageDownCommand}'><RepeatButton.Template><ControlTemplate><Border Background='Transparent'/></ControlTemplate></RepeatButton.Template></RepeatButton></Track.IncreaseRepeatButton></Track></ControlTemplate></Setter.Value></Setter></Style>");
        var style=new Style(typeof(CheckBox));style.Setters.Add(new Setter(Control.FocusVisualStyleProperty,null));style.Setters.Add(new Setter(Control.PaddingProperty,new Thickness(1,4,1,4)));
        var row=new FrameworkElementFactory(typeof(DockPanel));row.SetValue(FrameworkElement.VerticalAlignmentProperty,VerticalAlignment.Center);
        var box=new FrameworkElementFactory(typeof(Border),"Box");box.SetValue(FrameworkElement.WidthProperty,19.0);box.SetValue(FrameworkElement.HeightProperty,19.0);box.SetValue(Border.CornerRadiusProperty,new CornerRadius(6));box.SetValue(Border.BackgroundProperty,Dock.B("#18FFFFFF"));box.SetValue(Border.BorderBrushProperty,Dock.B("#5B9CA8AE"));box.SetValue(Border.BorderThicknessProperty,new Thickness(1));box.SetValue(DockPanel.DockProperty,System.Windows.Controls.Dock.Left);box.SetValue(FrameworkElement.VerticalAlignmentProperty,VerticalAlignment.Center);
        var tick=new FrameworkElementFactory(typeof(TextBlock),"Tick");tick.SetValue(TextBlock.TextProperty,"✓");tick.SetValue(TextBlock.FontSizeProperty,14.0);tick.SetValue(TextBlock.FontWeightProperty,FontWeights.Bold);tick.SetValue(TextBlock.ForegroundProperty,Dock.B("#203638"));tick.SetValue(FrameworkElement.HorizontalAlignmentProperty,HorizontalAlignment.Center);tick.SetValue(FrameworkElement.VerticalAlignmentProperty,VerticalAlignment.Center);tick.SetValue(UIElement.OpacityProperty,0.0);box.AppendChild(tick);row.AppendChild(box);
        var content=new FrameworkElementFactory(typeof(ContentPresenter));content.SetValue(ContentPresenter.ContentProperty,new TemplateBindingExtension(ContentControl.ContentProperty));content.SetValue(FrameworkElement.MarginProperty,new Thickness(11,0,0,0));content.SetValue(FrameworkElement.VerticalAlignmentProperty,VerticalAlignment.Center);row.AppendChild(content);
        var template=new ControlTemplate(typeof(CheckBox)){VisualTree=row};var selected=new Trigger{Property=CheckBox.IsCheckedProperty,Value=true};selected.Setters.Add(new Setter(Border.BackgroundProperty,Dock.B("#ADDCD5"),"Box"));selected.Setters.Add(new Setter(Border.BorderBrushProperty,Brushes.Transparent,"Box"));selected.Setters.Add(new Setter(UIElement.OpacityProperty,1.0,"Tick"));template.Triggers.Add(selected);
        var focus=new Trigger{Property=UIElement.IsKeyboardFocusedProperty,Value=true};focus.Setters.Add(new Setter(Border.BorderBrushProperty,Dock.B("#D7FFF5"),"Box"));template.Triggers.Add(focus);
        var disabled=new Trigger{Property=UIElement.IsEnabledProperty,Value=false};disabled.Setters.Add(new Setter(UIElement.OpacityProperty,.45));template.Triggers.Add(disabled);style.Setters.Add(new Setter(Control.TemplateProperty,template));app.Resources[typeof(CheckBox)]=style;
    }
}
